<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Throwable; use Illuminate\View\View; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Illuminate\Support\Facades\Http; use Pterodactyl\Services\Dezerx\Ai\Ai; use Pterodactyl\Services\Dezerx\Ai\ModelHttp; use Pterodactyl\Http\Controllers\Controller; class AiController extends Controller { public function __construct(private readonly AlertsMessageBag $alert) { } public function index(): View { return view('admin.dezerx.ai.index', ['enabled' => Ai::enabled(), 'provider' => Ai::provider(), 'providers' => Ai::providerLabels(), 'defaultModels' => Ai::defaultModels(), 'model' => (string) (Ai::blob()['model'] ?? ''), 'baseUrl' => Ai::baseUrl(), 'keyMode' => Ai::keyMode(), 'allowWrites' => Ai::allowWrites(), 'maxSteps' => Ai::maxSteps(), 'timeBudget' => Ai::timeBudget(), 'limit' => Ai::limit(), 'system' => (string) (Ai::blob()['system'] ?? ''), 'defaultPrompt' => Ai::DEFAULT_PROMPT, 'keys' => Ai::panelKeys(), 'keyless' => array_values(array_filter(Ai::providers(), Ai::keyless(...)))]); } public function update(Request $request): RedirectResponse { $data = $request->validate(['provider' => ['required', 'string'], 'model' => ['nullable', 'string', 'max:120'], 'base_url' => ['nullable', 'string', 'max:300'], 'key_mode' => ['required', 'string'], 'max_steps' => ['required', 'integer', 'between:1,30'], 'time_budget' => ['required', 'integer', 'between:30,600'], 'limit_messages' => ['required', 'integer', 'between:1,120'], 'limit_minutes' => ['required', 'integer', 'between:1,1440'], 'system' => ['nullable', 'string', 'max:8000']]); $provider = Ai::sanitiseProvider($data['provider']); $keyMode = Ai::sanitiseKeyMode($data['key_mode']); $baseUrl = Ai::sanitiseBaseUrl($data['base_url'] ?? ''); if ($provider === null || $keyMode === null) { $this->alert->danger('That is not a service this panel knows how to talk to.')->flash(); return redirect()->route('admin.dezerx.ai'); } if ($baseUrl === null) { $this->alert->danger('The address has to be an http:// or https:// URL, it is where this panel will send an API key.')->flash(); return redirect()->route('admin.dezerx.ai'); } $model = trim((string) ($data['model'] ?? '')); $cleared = false; if ($provider !== Ai::provider() && $model !== '' && $model === (string) (Ai::blob()['model'] ?? '')) { $model = ''; $cleared = true; } Ai::write(['enabled' => $request->boolean('enabled'), 'allow_writes' => $request->boolean('allow_writes'), 'provider' => $provider, 'model' => $model, 'base_url' => $baseUrl, 'key_mode' => $keyMode, 'max_steps' => (int) $data['max_steps'], 'time_budget' => (int) $data['time_budget'], 'limit_messages' => (int) $data['limit_messages'], 'limit_minutes' => (int) $data['limit_minutes'], 'system' => trim((string) ($data['system'] ?? ''))]); $this->alert->success($cleared ? 'The assistant settings have been saved. The model was cleared because it belonged to the previous service, so ' . Ai::model() . ' will be used.' : 'The assistant settings have been saved.')->flash(); return redirect()->route('admin.dezerx.ai'); } public function key(Request $request): RedirectResponse { $data = $request->validate(['provider' => ['required', 'string'], 'key' => ['nullable', 'string', 'max:400']]); $provider = Ai::sanitiseProvider($data['provider']); if ($provider === null) { $this->alert->danger('No such service.')->flash(); return redirect()->route('admin.dezerx.ai'); } Ai::setPanelKey($provider, $data['key'] ?? null); $this->alert->success(trim((string) ($data['key'] ?? '')) === '' ? 'That key has been removed.' : 'That key has been saved.')->flash(); return redirect()->route('admin.dezerx.ai'); } public function test(): RedirectResponse { $provider = Ai::provider(); $key = Ai::panelKey(); if ($key === null && !Ai::keyless($provider)) { $this->alert->danger('There is no key saved for ' . $provider . ' yet.')->flash(); return redirect()->route('admin.dezerx.ai'); } $model = Ai::model(); $prompt = [['role' => 'user', 'content' => 'Reply with the word: ready']]; try { $response = $provider === 'anthropic' ? Http::withHeaders(['x-api-key' => $key, 'anthropic-version' => '2023-06-01'])->connectTimeout(10)->timeout(60)->post('https://api.anthropic.com/v1/messages', ['model' => $model, 'max_tokens' => 1024, 'messages' => $prompt]) : Http::withToken((string) $key) ->withHeaders(str_contains((string) Ai::baseUrlFor($provider), 'opencode.ai/zen/go') ? ['x-opencode-session' => 'stark-test-' . bin2hex(random_bytes(8)), 'User-Agent' => 'DezerX-Stark-Assistant/1.0'] : []) ->connectTimeout(10)->timeout(60)->post((Ai::baseUrlFor($provider) ?: 'https://api.openai.com/v1') . '/chat/completions', ['model' => $model, 'messages' => $prompt]); } catch (Throwable $e) { $this->alert->danger('That service could not be reached: ' . $e->getMessage())->flash(); return redirect()->route('admin.dezerx.ai'); } if ($response->successful()) { $this->alert->success($model . ' answered. The assistant is ready to use.')->flash(); return redirect()->route('admin.dezerx.ai'); } $reason = ModelHttp::reason($response); $replacement = ModelHttp::replacement($response); $advice = match (true) { $replacement !== null => " The service suggests {$replacement}: put that in the model box (the assistant already falls back to it on its own).", $response->status() === 404 => ' The model name is probably wrong or retired for this service; leave the model box blank to use ' . (Ai::defaultModel($provider) ?: 'the service default') . '.', $response->status() === 403 && str_contains(strtolower($reason), 'denied access') => ' The service has blocked the account or project this key belongs to. No setting here can fix that; a key from another project or account is needed.', default => '', }; $this->alert->danger("{$model} on {$provider} answered " . $response->status() . ': ' . $reason . $advice)->flash(); return redirect()->route('admin.dezerx.ai'); } } 